def transform(grid):
    out = [row[:] for row in grid]
    pattern = [7, 7, 5, 7, 5]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 6:
                for j, color in enumerate(pattern):
                    k = c - 2 + j
                    if 0 <= k < len(row):
                        out[r][k] = color
    return out
